export function findById(id){return ACCOUNTS.find(x=>x.id===id)}
export function search(q){const s=String(q||'').toLowerCase();if(!s)return ACCOUNTS.slice();return ACCOUNTS.filter(x=>JSON.stringify(x).toLowerCase().includes(s))}
export function enabledOnly(){return ACCOUNTS.filter(x=>x.enabled!==false)}
export const COUNT=ACCOUNTS.length;

